      <line x1="305" y1="275" x2="385" y2="165" class="context-line" :style="{strokeOpacity:effectivePermeability/100}"/><line x1="385" y1="65" x2="385" y2="165" class="context-line" :style="{strokeOpacity:impulseSalience/100}"/><line x1="475" y1="110" x2="385" y2="165" class="context-line" :style="{strokeOpacity:coherence/100}"/>
