      <g class="context-node"><circle cx="305" cy="275" r="17" :style="{fillOpacity:effectivePermeability/100}"/><text x="305" y="305" text-anchor="middle">{{nl?'gedeelde context':'shared context'}}</text><circle cx="385" cy="65" r="17" :style="{fillOpacity:impulseSalience/100}"/><text x="385" y="39" text-anchor="middle">{{nl?'emotie':'emotion'}}</text><circle cx="475" cy="110" r="17" :style="{fillOpacity:coherence/100}"/><text x="507" y="114" text-anchor="start">{{nl?'doelen':'goals'}}</text></g>
