     <label class="coordination-control"><span><b>{{nl?'Besluitvorming':'Decision process'}}</b></span><select v-model="coordination"><option value="central">{{nl?'centrale coördinatie':'central coordination'}}</option><option value="democratic">{{nl?'overleg / democratisch':'deliberative / democratic'}}</option><option value="competitive">{{nl?'concurrentie':'competition'}}</option><option value="alternating">{{nl?'afwisselende regie':'alternating control'}}</option></select></label>
     <div class="position-tabs" role="tablist" :aria-label="nl?'Zelfpositie bewerken':'Edit self-position'"><button v-for="(position,index) in visiblePositions" :key="position.id" type="button" :class="{active:selectedPosition===index}" @click="selectedPosition=index">{{nl?'Positie':'Position'}} {{index+1}}</button></div>
     <label><span><b>{{nl?'Bewuste toegang':'Conscious access'}}</b><output>{{selectedSelfPosition.conscious}}%</output></span><input v-model.number="selectedSelfPosition.conscious" type="range" min="0" max="100"></label>
     <label><span><b>{{nl?'Ervaren eigenaarschap':'Experienced ownership'}}</b><output>{{selectedSelfPosition.ownership}}%</output></span><input v-model.number="selectedSelfPosition.ownership" type="range" min="0" max="100"></label>
     <label><span><b>{{nl?'Gedeeld geheugen':'Shared memory'}}</b><output>{{selectedSelfPosition.memory}}%</output></span><input v-model.number="selectedSelfPosition.memory" type="range" min="0" max="100"></label>
