      <g v-for="(position,index) in visiblePositions" :key="position.id" :class="['self-position',{selected:selectedPosition===index}]" @click="selectedPosition=index">
       <circle :cx="positionCoordinates[index].x" :cy="positionCoordinates[index].y" :r="31+position.conscious/10" :style="{fillOpacity:.12+.78*position.conscious/100,strokeOpacity:.25+.75*position.ownership/100}"/>
       <text :x="positionCoordinates[index].x" :y="positionCoordinates[index].y-5" text-anchor="middle">{{nl?'positie':'position'}} {{index+1}}</text><text :x="positionCoordinates[index].x" :y="positionCoordinates[index].y+14" text-anchor="middle" class="position-role">{{positionRoleLabels[position.role]}}</text>
